<script setup>
import { ref, onMounted, watch, computed } from 'vue'
import { Chart, registerables } from 'chart.js'
import { Bar, Doughnut } from 'vue-chartjs'
import { get, money } from '../services/api'
import { TrendingUp, Wallet, ChartNoAxesCombined, AlertTriangle, Sparkles } from 'lucide-vue-next'
Chart.register(...registerables)
const groups=ref([]), groupId=ref(''), data=ref(null), error=ref('')
async function loadGroups(){try{groups.value=await get('/groups');if(groups.value.length)groupId.value=String(groups.value[0].id)}catch(e){error.value=e.message}}
async function load(){if(!groupId.value)return;try{data.value=await get(`/groups/${groupId.value}/analytics`)}catch(e){error.value=e.message}}
watch(groupId,load);onMounted(loadGroups)
const categoryData=computed(()=>({labels:(data.value?.by_category||[]).map(x=>x.category),datasets:[{data:(data.value?.by_category||[]).map(x=>x.amount),backgroundColor:['#13a879','#5789e8','#9a7be7','#e8a64a','#e47777','#59b7c4','#6b8b9d','#a5b6c5'],borderWidth:0,hoverOffset:5}]}))
const monthData=computed(()=>({labels:(data.value?.by_month||[]).map(x=>x.month),datasets:[{label:'Spending',data:(data.value?.by_month||[]).map(x=>x.amount),backgroundColor:'#16a879',borderRadius:6,maxBarThickness:32}]}))
const chartOptions={responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false}},scales:{x:{grid:{display:false},ticks:{color:'#8290a3'}},y:{grid:{color:'rgba(130,144,163,.15)'},ticks:{color:'#8290a3'}}}}
</script>
<template>
  <div class="page-stack">
    <section class="page-intro"><div><div class="eyebrow">SPENDING INTELLIGENCE</div><h2>See the bigger picture.</h2><p>Real patterns from your group's expenses, without the spreadsheet headache.</p></div><div class="group-select"><label>Analyze group</label><select v-model="groupId"><option v-for="g in groups" :key="g.id" :value="String(g.id)">{{ g.name }}</option></select></div></section>
    <p v-if="error" class="alert alert-error">{{ error }}</p>
    <div v-if="!groups.length" class="panel empty-state large-empty"><div class="empty-icon"><ChartNoAxesCombined :size="26"/></div><h3>Your insights will appear here.</h3><p>Create a group and record expenses to see real analytics.</p><RouterLink to="/groups" class="btn btn-primary">Create a group</RouterLink></div>
    <template v-else-if="data">
      <div class="stats-grid analytics-stats"><article class="stat-card"><div class="stat-top"><span>Total spending</span><span class="stat-icon green"><Wallet :size="18"/></span></div><div class="stat-value">{{ money(data.total_spending) }}</div><div class="stat-foot">Across this group</div></article><article class="stat-card"><div class="stat-top"><span>Transactions</span><span class="stat-icon blue"><ChartNoAxesCombined :size="18"/></span></div><div class="stat-value">{{ data.expense_count }}</div><div class="stat-foot">Recorded expenses</div></article><article class="stat-card"><div class="stat-top"><span>Budget remaining</span><span class="stat-icon violet"><TrendingUp :size="18"/></span></div><div class="stat-value">{{ data.budget_remaining===null?'Not set':money(data.budget_remaining) }}</div><div class="stat-foot">{{ data.budget===null?'Add a group budget to track usage':`${data.budget_percent}% of budget used` }}</div></article></div>
      <section v-if="data.budget!==null" class="panel budget-panel"><div class="panel-heading"><div><h3>Budget guard</h3><p>{{ money(data.total_spending) }} spent of {{ money(data.budget) }}</p></div><span class="budget-percent" :class="{warning:data.budget_percent>=75,danger:data.budget_percent>=100}">{{ data.budget_percent }}%</span></div><div class="progress-track thick"><span :class="{warning:data.budget_percent>=75,danger:data.budget_percent>=100}" :style="{width:Math.min(100,data.budget_percent)+'%'}"></span></div><div class="budget-caption"><span>{{ data.budget_percent>=100?'Budget exceeded':data.budget_percent>=90?'Budget almost reached':data.budget_percent>=75?'Budget usage is getting high':'Spending is within budget' }}</span><span>{{ money(data.budget_remaining) }} remaining</span></div></section>
      <div class="analytics-grid"><section class="panel chart-panel"><div class="panel-heading"><div><h3>Spending by category</h3><p>Where the group's money goes.</p></div></div><div v-if="!data.by_category.length" class="empty-state compact">Add expenses to populate this chart.</div><div v-else class="doughnut-wrap"><Doughnut :data="categoryData" :options="{responsive:true,maintainAspectRatio:false,plugins:{legend:{position:'bottom',labels:{usePointStyle:true,boxWidth:7,padding:18,color:'#8290a3'}}}}"/></div></section><section class="panel chart-panel"><div class="panel-heading"><div><h3>Monthly spending</h3><p>Track spending over time.</p></div></div><div v-if="!data.by_month.length" class="empty-state compact">Add expenses to populate this chart.</div><div v-else class="bar-wrap"><Bar :data="monthData" :options="chartOptions"/></div></section></div>
      <section class="panel"><div class="panel-heading"><div><h3>Category breakdown</h3><p>Sorted by total spending.</p></div></div><div v-if="!data.by_category.length" class="empty-state compact">No category data yet.</div><div v-else class="category-breakdown"><div v-for="(c,i) in data.by_category" :key="c.category" class="category-line"><span class="category-rank">{{ String(i+1).padStart(2,'0') }}</span><div class="category-line-main"><div class="category-line-label"><strong>{{ c.category }}</strong><span>{{ data.total_spending?Math.round(c.amount/data.total_spending*100):0 }}%</span></div><div class="progress-track"><span :style="{width:(data.total_spending?c.amount/data.total_spending*100:0)+'%'}"></span></div></div><strong>{{ money(c.amount) }}</strong></div></div></section>
      <section class="insight-strip"><div class="insight-icon"><Sparkles :size="19"/></div><div><strong>{{ data.by_category.length?`${data.by_category[0].category[0].toUpperCase()+data.by_category[0].category.slice(1)} is your top spending category.`:'Your insights are warming up.' }}</strong><p>{{ data.by_category.length?`${money(data.by_category[0].amount)} has been recorded in this category. These observations are based on your group's actual expense records.`:'Record a few expenses to reveal useful spending patterns.' }}</p></div></section>
    </template>
  </div>
</template>
